function makeLimiter(max) {
  let count = 0;
  return function tryConsume() {
    if (count >= max) return false;
    count += 1;
    return true;
  };
}

const gate = makeLimiter(2);
gate(); // true
gate(); // true
gate(); // false — count lives in closure

